settings.custom_css:
.kpis-box:hover p{
    color: #fff !important;
}

.kpis-box:hover hr, .kpis-box1:hover hr{
    background-color: #fff !important;
}
.kpis-box1 svg{
    fill: transparent !important;
}
.kpis-box1:hover svg path {

    stroke: #fff !important;
}
.kpis-box:hover svg path {
    fill: #fff !important;
    stroke: #fff !important;
}

.timeline {
    position: relative;
}

.timeline::before {
    content: "";
    position: absolute;
    left: 23px; /* circle ke center pe adjust karo */
    top: 45px;
    width: 2px;
    height: 87%;
    background: linear-gradient(180deg, #2064AF 0%, #7FB63F 100%);; /* ya light color */
}
